window.fetchResult = null;
async function searchModels() {
  const params = new URLSearchParams({
    'filter': 'cc-by-sa-4.0',
    'sort': 'likes',
    'direction': '-1',
    'limit': '20'
  });
  const url = `https://huggingface.co/api/models?${params}`;
  const response = await fetch(url);
  const data = await response.json();
  return {url, count: data.length, firstFew: data.slice(0, 5).map(m => ({id: m.id, likes: m.likes}))};
}
searchModels().then(r => { window.fetchResult = r; });
'Fetching...';

